CREATE TABLE IF NOT EXISTS employees (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employee_number text UNIQUE NOT NULL, full_name text NOT NULL, work_email text, phone text, position_id uuid REFERENCES org_positions(id), department_id uuid REFERENCES org_departments(id), employment_status text NOT NULL DEFAULT 'Planned', employment_type text NOT NULL DEFAULT 'Full-time', jurisdiction text NOT NULL DEFAULT 'Nigeria', start_date date, manager_employee_id uuid REFERENCES employees(id), succession_status text DEFAULT 'Not Assessed', notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());